  str_n32_multiline_24_name = "Ramalan",
  str_n32_multiline_1_name_desc = "Joshua berubah menjadi monster dan menyerangmu. Jakine buru-buru meluncurkan mantra untuk memindahkan semua orang dari Crystal of Eternal Memory, dan ketika Anda sadar ...",
  str_n32_multiline_2_name_desc = "—",
  str_n32_multiline_3_name_desc = "Anda berpisah untuk mengambil dua jalur terpisah, sesuai rencana, dan menunggu Kegelapan Angel muncul. Namun, hal-hal yang hampir tidak pernah sesederhana itu sekarang, bukan?",
  str_n32_multiline_4_name_desc = "Seekor naga hitam pekat dan pasukan pemberontak yang menakutkan... Pertunjukan yang bagus akan segera dimulai.",
  str_n32_multiline_5_name_desc = "Waktu mengalir mundur lagi, kenangan lama dan hambatan baru menunggu kedatangan Anda.",
  str_n32_multiline_6_name_desc = "Pesta Anda bertemu dengan Lady Joshua lagi, tetapi ceritanya berubah secara tak terduga tanpa kehadiran Anda.",
  str_n32_multiline_7_name_desc = "Sebagai Schwartz menghadapi Kegelapan Angel dalam pertempuran satu lawan satu, pemberontakan akan dimulai, dan naga siap untuk terbang, kali ini...",
  str_n32_multiline_8_name_desc = "Kali ini, Mia bertahan. Akankah ada orang lain yang seberuntung itu?",
  str_n32_multiline_9_name_desc = "—",
  str_n32_multiline_10_name_desc = "Tragedi masih menemukan cara untuk menyerang, tetapi Anda tidak punya waktu untuk berhenti dan beristirahat.",
  str_n32_multiline_11_name_desc = "Rencana untuk perjalanan terakhir kembali ke masa lalu telah dibuat. Sekarang, perlombaan melawan waktu dimulai.",
  str_n32_multiline_12_name_desc = "Anda menemukan Dark Angel, tapi menenangkannya mungkin lebih sulit dari yang diharapkan...",
  str_n32_multiline_13_name_desc = "Kepakan sayap kupu-kupu dapat memicu badai. Segera, semua bagian Anda akan disejajarkan.",
  str_n32_multiline_14_name_desc = "—",
  str_n32_multiline_15_name_desc = "Hanya White Queen yang tersisa di papan, dan dia mempertaruhkan semuanya pada satu langkah putus asa terakhir.",
  str_n32_multiline_16_name_desc = "—",
  str_n32_multiline_17_name_desc = "Diundang ke aula besar Schwartz Mansion, Anda mendengar seseorang berbicara di balik pintu.",
  str_n32_multiline_18_name_desc = "Saat Anda bersiap untuk pergi Schwartz Mansion, Anda menemukan setumpuk surat terbakar di tengah area berumput di taman belakang...",
  str_n32_multiline_19_name_desc = "Di jalan kecil menuju Schwartz Mansion, seorang gadis berambut merah tiba-tiba menghalangi jalan Sharona.",
  str_n32_multiline_20_name_desc = "Bersembunyi di dekat alun-alun, Anda secara tidak sengaja mendengar percakapan antara dua teman lama.",
  str_n32_multiline_21_name_desc = "Di sebuah jalan di Uptown, dua orang yang tampaknya tidak berhubungan sedang membicarakan sesuatu yang perlu Anda perhatikan...",
  str_n32_multiline_22_name_desc = "Di jalan kecil menuju Schwartz Mansion, sebuah menara tinggi runtuh dengan tabrakan ...",
  str_n32_multiline_23_name_desc = "Di tengah kekacauan, Anda menemukan dua bangsawan yang terjebak di tempat.",
  str_n32_multiline_24_name_desc = "Di jalan kecil menuju Schwartz Mansion, sebuah menara tinggi telah runtuh...",
  str_n32_multiline_1_name_desc_long = "Jakine telah gagal. Anda tidak dapat meninggalkan Crystal of Eternal Memory, tetapi berhasil melacak waktu sebelum pawai dimulai. Joshua, yang telah menjadi monster yang dikenal sebagai Dark Angel, menyerang Anda sekali lagi. Setelah melawannya, Anda mencoba untuk pergi, meskipun keputusasaan Anda memuncak, tetapi tetap tidak membuat kemajuan. Pada saat ini, yang lain Joshua muncul.",
  str_n32_multiline_2_name_desc_long = "Joshua menjelaskan keseluruhan cerita untuk Anda. Ternyata itu Joshua tidak pernah mati, tetapi telah membatasi dirinya dan kepribadian tak terkendali yang terpisah dari benihnya ke Crystal of Eternal Memory. Untuk menghemat Joshua dan tinggalkan tempat ini, Anda membuat rencana untuk menekan Kegelapan Angel.",
  str_n32_multiline_3_name_desc_long = "Anda dibagi menjadi dua kelompok sesuai dengan rencana. Mia tiba di tribun, sementara yang lain berhasil memikat Kegelapan Angel keluar. Segalanya tampak berjalan sempurna ketika pemberontakan dimulai lebih awal karena alasan yang tidak diketahui. Musuh aneh dan naga yang tampak asing menyerang tribun, membuat rencana Anda kacau balau.",
  str_n32_multiline_4_name_desc_long = "Anda mengalahkan Kegelapan Angel, tetapi situasi di sekitar Anda merosot lebih dalam ke dalam keputusasaan setiap detik. Pasukan pemberontak, naga terbang, dan mania yang bangkit terus menyebar ke seluruh kerumunan, bahkan mengubah wajah Joshua menjadi gambaran keganasan yang tidak bisa dikenali. Rekan-rekanmu dilahap oleh lubang korupsi, satu demi satu, dan sama seperti kamu tenggelam dalam keputusasaan, Jakine merapalkan mantra perjalanan waktu sekali lagi...",
  str_n32_multiline_5_name_desc_long = "Waktu mengalir mundur, dan semua orang di taman sekali lagi terlibat dalam pertempuran melawan Kegelapan Angel. Hanya kamu yang masih dikejar oleh para penjaga dengan ekspresi seram mereka... Apa yang sebenarnya terjadi disini? Saat Anda bersembunyi, berpegang teguh pada kehidupan tercinta, Anda tersesat dalam kontemplasi.",
  str_n32_multiline_6_name_desc_long = "Mirip dengan pertama kali Anda melakukan perjalanan kembali ke masa lalu, semua orang bertemu Joshua lagi, tapi kali ini, sepertinya begitu Schwartz Dan Joshua berselisih. Karena alasan ini, Caleb dibiarkan berdiri di samping Jakine, dan Schwartz menghadapi Kegelapan Angel sendiri.",
  str_n32_multiline_7_name_desc_long = "Dalam pertempuran satu lawan satu berikutnya, Schwartz dan Kegelapan Angel seimbang, tapi Dark Angel tiba-tiba berbicara dengan suara Joshua, mengutuk perilaku Schwartz yang tidak bertanggung jawab terhadap keluarganya. Pada saat yang sama, pemberontakan dimulai, dan Anda menyadari bahwa Anda harus memanfaatkan kesempatan untuk berkumpul kembali dengan yang lain. Namun, pada saat inilah Anda menyaksikan Kegelapan Angel menghentikan naga dari menyerang tribun.",
  str_n32_multiline_8_name_desc_long = "Kali ini, Mia bertahan. Namun, muda Carleen terpengaruh karena cedera, dan memilih untuk mengambil nyawanya sendiri untuk melindungi keluarganya. Semangat Mia akan runtuh dalam situasi, pada saat seperti itu, Dark yang sekarat Angel mengambil Mia ke dalam pelukannya dan memeluknya erat-erat. Pada saat inilah Schwartz menjadi yakin bahwa Dark Angel sebenarnya adalah istrinya.",
  str_n32_multiline_9_name_desc_long = "Di rumah besar, Joshua menjelaskan kebenaran kepada Caleb. Ternyata itu Joshua adalah pembunuh dari faksi lawan Schwartz, dan bukan saudara kandung Caleb. Dia mencoba membujuk Caleb untuk membantunya melenyapkan yang lain, dan meskipun Caleb tidak meragukan identitas Joshua, dia tidak mau membantunya dan akhirnya dibunuh oleh Joshua. Joshua.",
  str_n32_multiline_10_name_desc_long = "Anda dan Mia tiba di mansion untuk menemukan kediaman dalam kekacauan total, dan dengan bantuan Ms. Rot, Anda berhasil melarikan diri bersama Jakine. Anda secara kasar mengklarifikasi kebenaran masalah ini dengan mengatur kecerdasan yang diperoleh melalui perjalanan dua kali perjalanan—perjalanan kembali ke masa lalu ini akan menjadi kesempatan terakhir Anda.",
  str_n32_multiline_11_name_desc_long = "Anda menghindari pengejar Anda seperti yang direncanakan, dan datang sebelumnya Joshua sesuai jadwal. Permainan catur baru akan segera dimulai.",
  str_n32_multiline_12_name_desc_long = "Anda mencoba untuk menenangkan Dark Angel dengan menyanyikan lagu yang dia nyanyikan Mia. Ini mengingatkan Dark Angel masa lalunya, di mana upaya pembunuhan gagal dan dia dimenangkan oleh yang muda Schwartz... Kenangannya jelas, membuatnya semakin sulit untuk memaafkan Schwartz.",
  str_n32_multiline_13_name_desc_long = "Schwartz tidak bisa melihat Dark Angel tetapi bertemu dengan tentara yang mengejar Anda. Anda membimbing semua orang ke tribun sebelum naga menyerang dan berhasil melawannya. Mia juga telah menghibur si Kegelapan Angel, sementara Ms. Rot tetap bersama Joshua, dan banyak hal berubah secara dramatis menjadi lebih baik.",
  str_n32_multiline_14_name_desc_long = "Kebenaran mungkin sulit diterima, tapi untuk terus melangkah maju, kita harus belajar menghadapi itu semua. Kaleb, Schwartz, kegelapan Angel, Mia, dan Nona Rot... Saat pertempuran terakhir semakin dekat, setiap orang memiliki kebenarannya sendiri yang terukir kuat di hati mereka.",
  str_n32_multiline_15_name_desc_long = "Anda bertarung dalam pertempuran yang menentukan melawan Iblis Putih dan mendorongnya ke jurang kekalahan. Iblis Putih bermaksud menyeretmu ke kuburan bersamanya, sedangkan Iblis Hitam Angel memilih menghadapi Iblis Putih sendirian setelah berdamai dengan keluarganya. Dua diri yang terpecah akhirnya bertemu lagi.",
  str_n32_multiline_16_name_desc_long = "Anda berhasil meninggalkan Crystal of Eternal Memory setelah menyimpan Joshua. Namun, Joshua tampaknya telah kehilangan semua ingatannya dan memilih untuk memulai perjalanan baru sendirian. Saat sulit menghadapi masa kini, orang kerap memilih membenamkan diri di masa lalu sebagai sarana pelarian. Hanya ketika orang mendapatkan kembali keberanian untuk hidup, kita dapat bergerak menuju masa depan yang baru.",
  str_n32_multiline_17_name_desc_long = "—",
  str_n32_multiline_18_name_desc_long = "—",
  str_n32_multiline_19_name_desc_long = "—",
  str_n32_multiline_20_name_desc_long = "—",
  str_n32_multiline_21_name_desc_long = "—",
  str_n32_multiline_22_name_desc_long = "—",
  str_n32_multiline_23_name_desc_long = "—",
  str_n32_multiline_24_name_desc_long = "—",
  str_n32_multiline_doc_lock = "Mari melangkah maju dengan berani. Mungkin kita akan mengalami beberapa pertemuan tak terduga di sepanjang jalan.",
  str_n32_multiline_doc_role_1 = "Ms. Blanc",
  str_n32_multiline_doc_role_2 = "Yosua",
  str_n32_multiline_doc_role_3 = "Sharona",
  str_n32_multiline_doc_role_4 = "Otto",
  str_n32_multiline_doc_roledesc_1 = "Mantan Kapten Nightwatch, yang usianya menjadi misteri.\nDia terluka dan mundur selama Pertempuran Umbraton di Kalender Pagi Tahun 1988 setelah dikepung oleh Darkover, dan kemudian menjadi pemandu wisata yang elegan.\nSampai hari ini, legenda tentang identitasnya yang dulu—Ms. Busuk, pembawa kematian dan kehancuran—masih tertinggal di sudut sunyi Lumopolis...",
  str_n32_multiline_doc_roledesc_2 = [[
Putri seorang sarjana terkenal dan "almarhum istri" Penguasa Kota. Saat itu, di bawah tekanan besar, dia jatuh cinta dan menikah Schwartz. Namun, ayahnya tidak sempat melihat hari pernikahannya, karena dia meninggal dalam kebakaran.
Di Kalender Pagi 1992, secara resmi diumumkan hal itu Joshua telah meninggal karena sakit.]],
  str_n32_multiline_doc_roledesc_3 = "Lahir di Lumopolis, dia diberitahu di usia muda bahwa kedua orang tuanya telah meninggal dunia dan diasuh oleh para tetua keluarga Kartima. Pada Kalender Pagi 1988, keluarga Kartima menjadi buronan Lumopolis karena melakukan kudeta, dan Sharona untungnya berhasil melarikan diri dari kota. Dia kemudian bergabung dengan pasukan koalisi untuk mengambil bagian dalam serangan balik melawan Darkover, dan akhirnya menjadi Komandan Legiun Illumina.",
  str_n32_multiline_doc_roledesc_4 = "Lahir dari keluarga Troy yang kuat, yang lingkungan pengaruh utamanya adalah Dewan Penatua. Setelah Tuan Kota sebelumnya dibunuh, desas-desus mulai mengarah ke keluarga Troy, tetapi desas-desus ini dengan cepat menghilang. Dia telah merencanakan untuk melatih keponakannya sebagai penggantinya, namun dia kemudian secara resmi terdaftar sebagai almarhum.",
  str_n32_multiline_doc_name_1 = "Latar Belakang Nona Blanc",
  str_n32_multiline_doc_name_2 = "Surat untuk Montague",
  str_n32_multiline_doc_name_3 = "Kisah Gadis Berambut Merah",
  str_n32_multiline_doc_name_4 = "Roshee Kembali ke Jalan yang Benar",
  str_n32_multiline_doc_name_5 = "Surat Pembakaran",
  str_n32_multiline_doc_name_6 = "Gadis Berambut Merah dan Tetua",
  str_n32_multiline_doc_name_7 = "Montase Rumah",
  str_n32_multiline_doc_name_8 = "Gadis Nubuat",
  str_n32_multiline_doc_tips_1 = "Peristiwa Sebelumnya Latar Belakang Ms. Blanc Tidak Terkunci",
  str_n32_multiline_doc_tips_2 = "Surat Peristiwa Sebelumnya ke Montagues Tidak Terkunci",
  str_n32_multiline_doc_tips_3 = "Peristiwa Sebelumnya Kisah Gadis Berambut Merah Tidak Terkunci",
  str_n32_multiline_doc_tips_4 = "Peristiwa Sebelumnya Roshee Kembali ke Jalan yang Benar Tidak Terkunci",
  str_n32_multiline_doc_tips_5 = "Peristiwa Sebelumnya Surat Pembakaran Tidak Terkunci",
  str_n32_multiline_doc_tips_6 = "Peristiwa Sebelumnya Gadis Berambut Merah dan Penatua Tidak Terkunci",
  str_n32_multiline_doc_tips_7 = "Acara Sebelumnya Rumah Montague Tidak Terkunci",
  str_n32_multiline_doc_tips_8 = "Peristiwa Sebelumnya Maiden of Prophecy Tidak Terkunci",
  str_n32_multiline_doc_desc_1 = "Ms. Blanc adalah kerabat jauh Lady JoshuaNamun, keduanya tidak memiliki hubungan darah. Ms. Blanc menunjukkan bakat luar biasa sejak usia muda, tetapi mengalami frustrasi karena tidak memiliki tempat untuk memanfaatkan kemampuannya dengan baik. Dihadapkan dengan restu campuran karena memiliki anak yang berbakat, orang tuanya tidak punya pilihan selain menyerahkannya ke tangan Caleb, tetapi setelah itu dia secara tak terduga bertemu dengan Lady. Joshua. Keduanya cocok, membangun hubungan yang kuat dan terlibat dalam percakapan yang hidup sejak pertemuan pertama mereka. Sebagai akibat, Joshua diajari Ms. Blanc bertahun-tahun.",
  str_n32_multiline_doc_desc_2 = "Di tumpukan surat-surat yang terbakar tersembunyi sebuah surat untuk Anak Montagues, yang ditulis oleh ayah Caleb. Dalam surat itu, ayah Caleb tampaknya telah membuat semacam resolusi, menawarkan keinginan yang tulus kepada penerima.",
  str_n32_multiline_doc_desc_3 = "Seorang ibu dengan Dragonkin terbangun telah melahirkan dua anak perempuan. Warisannya membuatnya kehilangan kendali dan dia dibunuh oleh keluarganya. Untuk melindungi naganya yang akan menetas, sang putri sulung memilih mengembara hingga menetap di Umbraton. Putri bungsu tumbuh tanpa mengetahui ibunya dibunuh oleh sukunya.",
  str_n32_multiline_doc_desc_4 = "Meskipun Otto tidak memiliki anak sendiri, dia selalu merawat keponakannya Roshee, yang kemudian menjadi salah satu dari Empat Malaikat, Michael, seolah-olah dia adalah putrinya sendiri. Ketika dia masih muda, Roshee suka berkeliaran di gang dan jalan, menangkap pencuri dan penjahat lainnya, tetapi di bawah bimbingan Otto, dia secara bertahap mengubah pikirannya ke hal-hal yang lebih besar. Di Kalender Pagi Tahun 1988, Roshee tiba-tiba kabur dari rumah tanpa peringatan sedikit pun.",
  str_n32_multiline_doc_desc_5 = "Alasan keponakan Otto, Roshee, melarikan diri dari rumah adalah karena dia menerima catatan yang mencantumkan semua bukti yang menunjukkan bahwa pamannya Otto adalah orang yang menempatkan Eclipsites di Lumopolis setahun sebelumnya dan menghasut pemberontakan. Roshee tidak dapat menerima kenyataan ini, percaya bahwa pamannya tidak akan pernah melakukan hal seperti itu. Oleh karena itu, Roshee menitipkan surat untuk temannya Sharona, dan dia memutuskan untuk menjauh dari keluarganya dan bergabung dengan pasukan ekspedisi...",
  str_n32_multiline_doc_desc_6 = "Gadis berambut merah itu merobohkan menara tinggi tempat seorang sesepuh keluarga Kartima dipenjara karena melawan Pantomim. Yang mengejutkan gadis berambut merah itu, tetua itu mengatakan hal yang sama seperti yang dikatakan ibunya, \"Kamu bukan orang yang akan menyelamatkan keluarga Kartima.\" Gadis berambut merah itu tahu bahwa yang lebih tua telah menunggu adiknya Sharona, tetapi dia merasa hal-hal seperti itu tidak lagi penting baginya.",
  str_n32_multiline_doc_desc_7 = "Pyrrhus, Gautier... Montague. Ini adalah nama-nama rumah yang memberontak terhadap Schwartz keluarga—nama yang akhirnya hilang termakan waktu. Kebencian membutakan para penyintas, menjadikan mereka bidak yang ideal bagi calon konspirator.",
  str_n32_multiline_doc_desc_8 = "Sharona berlari ke tetua di samping menara yang runtuh. Penatua memberitahunya bahwa, menurut ramalan itu, Sharona adalah satu-satunya yang bisa menyelamatkan keluarga Kartima. Dia berharap untuk Sharona untuk mewarisi Azure Flame Katana diwariskan dari generasi ke generasi oleh para tetua keluarga Kartima, dan pada akhirnya memikul beban mengamankan masa depan kejayaan garis keturunan mereka.",
  str_n32_multiline_doc_lockdesc_1 = "Kapan <color=#ffe062>Retak</color>, dengarkan apa yang dikatakan penjaga di pintu masuk <color=#ffe062>aula Schwartz Rumah besar</color>.",
  str_n32_multiline_doc_lockdesc_2 = "Kapan <color=#ffe062>Retak</color>, perhatikan apa yang ada di bawah kaki Anda saat menuju ke <color=#ffe062>alun-alun pusat</color>...",
  str_n32_multiline_doc_lockdesc_3 = "Kapan <color=#ffe062>Retak</color>, seseorang tampaknya menghalangi jalan Anda saat Anda meninggalkan <color=#ffe062>alun-alun pusat</color>...",
  str_n32_multiline_doc_lockdesc_4 = "Ketika semuanya dimulai <color=#ffe062>Ledakan</color>, Anda tampaknya dapat mendengar beberapa suara saat bersembunyi di sekitar <color=#ffe062>alun-alun pusat</color>...",
  str_n32_multiline_doc_lockdesc_5 = "Ketika semuanya dimulai <color=#ffe062>Ledakan</color>, cari sosok yang sudah dikenal saat berjalan di sepanjang jalan setapak di sekitar <color=#ffe062>alun-alun pusat</color>.",
  str_n32_multiline_doc_lockdesc_6 = "Ketika semuanya dimulai <color=#ffe062>Ledakan</color>, perhatikan bentuk bangunan saat berangkat <color=#ffe062>alun-alun pusat</color>.",
  str_n32_multiline_doc_lockdesc_7 = "Ketika semuanya dimulai <color=#ffe062>Runtuh</color>, tunjukkan rute pelarian ke dua bangsawan di <color=#ffe062>alun-alun pusat</color>.",
  str_n32_multiline_doc_lockdesc_8 = "Ketika semuanya dimulai <color=#ffe062>Runtuh</color>, perhatikan menara yang runtuh saat meninggalkan <color=#ffe062>alun-alun pusat</color>.",
  str_n32_multiline_doc_unlock_1 = "Melakukan Ms. Blanc dan Nyonya Joshua berbagi sejarah seperti itu?!",
  str_n32_multiline_doc_unlock_2 = "Bagaimana mungkin ayah Caleb menulis surat seperti itu?!",
  str_n32_multiline_doc_unlock_3 = "Apakah kisah gadis berambut merah itu benar-benar hanya sebuah dongeng?",
  str_n32_multiline_doc_unlock_4 = "Tampaknya Otto juga memiliki kelemahan tak terduga...",
