  str_n32_multiline_main_intro_title = "<color=#68251b><size=55>Info Gameplay Divergence</size></color>",
  str_n32_multiline_main_intro_head_1 = "<color=#623d33><size=34>Masuki dunia Crystal of Eternal Memory</size></color>",
  str_n32_multiline_main_intro_body_1 = "<color=#ac7655><size=28>Dengan bantuan Jakine, Anda dapat kembali ke ruang dan waktu untuk menjelajahi Lumopolis lama. Dengan setiap upaya, Anda akan semakin dekat dengan kebenaran.</size></color>",
  str_n32_multiline_main_intro_head_2 = "<color=#623d33><size=34>Jangan lewatkan pertemuan di sepanjang jalan</size></color>",
  str_n32_multiline_main_intro_body_2 = "<color=#ac7655><size=28>Selama perjalanan Anda yang menegangkan, Anda akan mengalami pertempuran yang sulit dan bertemu orang yang berbeda. Saat Anda mendengarkan percakapan mereka, Anda mungkin dapat mengetahui peristiwa masa lalu yang hanya diketahui sedikit orang dan mendapatkan keuntungan yang tidak terduga.</size></color>",
  str_n32_multiline_main_intro_head_3 = "<color=#623d33><size=34>Koleksi Acara Sebelumnya</size></color>",
  str_n32_multiline_main_intro_body_3 = "<color=#ac7655><size=28>Peristiwa masa lalu yang Anda kumpulkan selama perjalanan akan diurutkan dalam Berkas, tempat Anda dapat menelusuri atau melihatnya kapan saja untuk menemukan petunjuk peristiwa masa lalu lainnya yang Anda lewatkan.</size></color>",
  str_n32_multiline_map_intro_title = "<color=#68251b><size=55>Info Gameplay Divergence</size></color>",
  str_n32_multiline_map_intro_head_1 = "<color=#623d33><size=34>Perjalanan Akhir Waktu</size></color>",
  str_n32_multiline_map_intro_body_1 = "<color=#ac7655><size=28>Meskipun Anda akan melakukan perjalanan ke Lumopolis setiap kali, Anda akan menghadapi pertempuran dan pertemuan yang berbeda di setiap perjalanan baru, jadi harap perhatikan setiap pertempuran dengan serius dan hargai setiap pertemuan.</size></color>",
  str_n32_multiline_map_intro_head_2 = "<color=#623d33><size=34>Pertemuan Perjalanan</size></color>",
  str_n32_multiline_map_intro_body_2 = "<color=#ac7655><size=28>Hargai setiap pertemuan dalam perjalanan Anda untuk merekam peristiwa masa lalu yang hanya diketahui sedikit orang. Acara yang lalu akan dikumpulkan di Dossiers, dan Anda dapat mengklaim hadiah setelah mengumpulkan semua acara yang lalu.</size></color>"
